class Solution {
public:
    bool isIsomorphic(string s, string t) {
        int mapST[256], mapTS[256];
        for (int i = 0; i < 256; i++) {
            mapST[i] = -1;
            mapTS[i] = -1;
        }
        for (int i = 0; i < (int)s.size(); i++) {
            int sc = (unsigned char)s[i];
            int tc = (unsigned char)t[i];
            if (mapST[sc] != -1 && mapST[sc] != tc) return false;
            if (mapTS[tc] != -1 && mapTS[tc] != sc) return false;
            mapST[sc] = tc;
            mapTS[tc] = sc;
        }
        return true;
    }
};
